 SUM(CASE WHEN (basisofrecord <> 'LIVING_SPECIMEN' AND (establishmentmeans.concept IS NULL OR establishmentmeans.concept NOT IN ('introduced','introducedAssistedColonisation','vagrant')) AND (degreeofestablishment.concept IS NULL OR degreeofestablishment.concept NOT IN ('managed','cultivated','captive','released','failing','casual','unestablished','reproducing','established','colonising','spreading','naturalized','invasive','widespreadInvasive')) AND NOT COALESCE(ARRAY_CONTAINS(issue,'TAXON_MATCH_FUZZY'),FALSE) AND (v_kingdom IS NULL OR LOWER(v_kingdom) NOT IN ('animalia','plantae','fungi') OR LOWER(kingdom) NOT IN ('animalia','plantae','fungi') OR LOWER(v_kingdom) = LOWER(kingdom))) AND datasetkey = '4fa7b334-ce0d-4e88-aaae-2e0c138d049e' THEN 1 ELSE 0 END) AS n_ebird,
