E '%botanic%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%jardin botanique%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%jardín botánico%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%jardim botânico%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%botanischer garten%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%orto botanico%') OR (LOWER(kingdom) = 'plantae' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%arboretum%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(locality,'')) LIKE '% zoo %' AND LOWER(COALESCE(locality,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(locality,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(locality,'')) LIKE '%zoo animal%' AND LOWER(COALESCE(locality,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(locality,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(habitat,'')) LIKE '% zoo %' AND LOWER(COALESCE(habitat,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(habitat,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(habitat,'')) LIKE '%zoo animal%' AND LOWER(COALESCE(habitat,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(habitat,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '% zoo %' AND LOWER(COALESCE(occurrenceremarks,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(occurrenceremarks,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(occurrenceremarks,'')) LIKE '%zoo animal%' AND LOWER(COALESCE(occurrenceremarks,'')) NOT LIKE '%not a zoo%' AND LOWER(COALESCE(occurrenceremarks,'')) NOT LIKE '%not a captive%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(locality,'')) LIKE '%zoo specimen%') OR (LOWER(kingdom) = 'animalia' AND LOWER(COALESCE(locality,''